    col_ones = [[0] * (n + 1) for _ in range(m)]
    for c in range(m):
        cnt = 0
        for r in range(n):
            if grid[r][c] == d:
                cnt += 1
            col_ones[c][r + 1] = cnt

    # helper: does row r have at least one d in columns [cl, cr] ?
    def row_has_d(r, cl, cr):
        return row_ones[r][cr + 1] - row_ones[r][cl] > 0

    # helper: does column c have at least one d in rows [rl, rr] ?
    def col_has_d(c, rl, rr):
        return col_ones[c][rr + 1] - col_ones[c][rl] > 0

    best_area = 0
    best_rect = None   # (i, j, l, r)
    best_other = None

    # 3. enumerate all row intervals
    for i in range(n):
        for j in range(i, n):
            # columns that have at least one d in this row interval
            col_has = [col_has_d(c, i, j) for c in range(m)]

            # enumerate column intervals
            for l in range(m):
                # quick reject: column l must have d
                if not col_has[l]:
                    continue
                for r in range(l, m):
                    # all columns in [l,r] must have a d
                    ok = True
                    for c in range(l, r + 1):
                        if not col_has[c]:
                            ok = False
                            break
                    if not ok:
                        continue

                    # every row in the interval must contain a d in these columns
                    ok = True
                    for row in range(i, j + 1):
                        if not row_has_d(row, l, r):
                            ok = False
                            break
                    if not ok:
                        continue

                    # check that exactly two distinct values appear in the rectangle
                    other_val = None
                    more_than_two = False
