                        continue

                    area = (j - i + 1) * (r - l + 1)
                    if area > best_area:
                        best_area = area
                        best_rect = (i, j, l, r)
                        best_other = other_val

    # If no suitable rectangle found (should not happen), return original grid
    if best_rect is None:
        return grid

    i, j, l, r = best_rect
    e = best_other                     # the non‑dominant value

    # 4. Determine columns that contain any non‑dominant value
    cols_with_non_d = set()
    for c in range(l, r + 1):
        for rr in range(i, j + 1):
            if grid[rr][c] != d:
                cols_with_non_d.add(c)
                break

    # 5. Build output grid
    out = []
    for rr in range(i, j + 1):
        row_has_non_d = any(grid[rr][c] != d for c in range(l, r + 1))
        if row_has_non_d:
            out.append([e] * (r - l + 1))
